const workbenchStageFromValueV1 = (value) => {
  const token = normalizeActivityRouteTextV1(value);
  if (!token) return null;
  const direct = STAGE_WORKBENCH.find((stage) =>
    [stage.key, stage.title, ...stage.aliases].some(
      (candidate) => normalizeActivityRouteTextV1(candidate) === token,
    ),
  );
  if (direct) return direct;
  // Algumas versões antigas exibem o cartão com o ID numérico de
  // `demoData.activities` (por exemplo, 1 = Terraplanagem). Converta esse
  // valor pelo nome da etapa antes de tentar qualquer fallback heurístico.
  const legacyStage = Array.isArray(demoData?.activities)
    ? demoData.activities.find(
        (item) =>
          String(item?.id ?? "") === String(value ?? "") ||
          normalizeActivityRouteTextV1(item?.name) === token,
      )
    : null;
  if (legacyStage) {
    const matching = STAGE_WORKBENCH.find(
      (stage) =>
        normalizeActivityRouteTextV1(stage.title) ===
          normalizeActivityRouteTextV1(legacyStage.name) ||
        stage.aliases.some(
          (alias) =>
            normalizeActivityRouteTextV1(alias) ===
            normalizeActivityRouteTextV1(legacyStage.name),
        ),
    );
    if (matching) return matching;
  }
  const model = Array.isArray(executionModel.stages)
    ? executionModel.stages.find((stage) =>
        [stage.key, stage.id, stage.name].some(
          (candidate) => normalizeActivityRouteTextV1(candidate) === token,
        ),
      )
    : null;
  if (model) {
    const modelToken = normalizeActivityRouteTextV1(model.key || model.name);
    const matching = STAGE_WORKBENCH.find(
      (stage) =>
        normalizeActivityRouteTextV1(stage.key) === modelToken ||
        normalizeActivityRouteTextV1(stage.title) ===
          normalizeActivityRouteTextV1(model.name) ||
        stage.aliases.some(
          (alias) => normalizeActivityRouteTextV1(alias) === modelToken,
        ),
    );
    if (matching) return matching;
  }
  const hinted = STAGE_WORKBENCH.find((stage) =>
    (activityRouteStageHintsV1[stage.key] || []).some((hint) =>
      token.includes(normalizeActivityRouteTextV1(hint)),
    ),
  );
  return hinted || null;
};
const workbenchActivityForValueV1 = (stage, value) => {
  const token = normalizeActivityRouteTextV1(value);
  if (!stage || !token) return stage?.activities?.[0] || null;
  const direct = stage.activities.find((item) =>
    [item.id, item.title].some(
      (candidate) => normalizeActivityRouteTextV1(candidate) === token,
    ),
  );
  if (direct) return direct;
  const partial = stage.activities.find((item) => {
    const itemToken = normalizeActivityRouteTextV1(item.id + " " + item.title);
    return itemToken.includes(token) || token.includes(itemToken);
  });
  if (partial) return partial;
  const packet =
    token.includes("prepar") || token.includes("frente")
      ? "front"
      : token.includes("execut") || token.includes("realiz")
        ? "execute"
        : token.includes("med") || token.includes("valid")
          ? "measure"
          : token.includes("liber") || token.includes("proxim")
            ? "release"
            : "";
  const packetIndex = {
    front: 0,
    execute: Math.min(1, stage.activities.length - 1),
    measure: Math.max(0, stage.activities.length - 2),
    release: stage.activities.length - 1,
  }[packet];
  return (
    stage.activities[packetIndex == null ? 0 : packetIndex] ||
    stage.activities[0]
  );
};
const workbenchActivityRouteV1 = (activityValue = "", stageValue = "") => {
  const raw = String(activityValue ?? "").trim();
  const parts = raw.split(":");
  const embeddedStage =
    parts.length > 1 ? workbenchStageFromValueV1(parts[0]) : null;
  const candidateStage =
    parts.length === 1 ? workbenchStageFromValueV1(raw) : null;
  const state = appStore.get?.() || {};
  const stateStage =
    state.selectedStageV9 || state.selectedStage || state.stageSelected || "";
  const stage =
    embeddedStage ||
    candidateStage ||
    workbenchStageFromValueV1(stageValue) ||
    workbenchStageFromValueV1(stateStage) ||
    STAGE_WORKBENCH[0];
  const requestedActivity = embeddedStage ? parts.slice(1).join(":") : raw;
  const activity =
    workbenchActivityForValueV1(stage, requestedActivity) ||
    findWorkbenchActivity(stage.key, stage.activities[0]?.id).activity;
  return runtimeRouteV1(
    "/admin/workers/activity",
    `stage=${encodeURIComponent(stage.key)}&activity=${encodeURIComponent(activity.id)}`,
  );
};
const ACTIVITY_ROUTE_BRIDGE_SELECTORS_V1 =
  "[data-v5362-activity],[data-v5360-stage-card],[data-v5356-stage-activity],[data-activity-v9],[data-activity-detail],[data-activity-open],[data-activity-card],[data-agenda-item]";
const installActivityRouteBridgeV1 = (root) => {
  if (!root || root.__activityRouteBridgeV1) return;
  root.__activityRouteBridgeV1 = true;
  root.addEventListener(
    "click",
    (event) => {
      const target = event.target?.closest?.(
        ACTIVITY_ROUTE_BRIDGE_SELECTORS_V1,
      );
      if (
        !target ||
        !root.contains(target) ||
        target.closest("[data-activity-location-editor]")
      )
        return;
      if (
        target.matches("[data-agenda-item-menu]") ||
        target.closest("[data-agenda-item-menu]")
      )
        return;
      if (
        target.matches("[data-activity-edit],[data-activity-delete]") ||
        target.closest("[data-activity-edit],[data-activity-delete]")
      )
        return;
      // A atividade da subpágina possui uma tela dedicada; apenas o botão
      // Editar deve atravessar para o Workbench do Worker.
      if (
        target.matches(
          "[data-activity-v9],[data-activity-open],[data-activity-card]",
        ) ||
        target.closest(
          "[data-activity-v9],[data-activity-open],[data-activity-card]",
        )
      )
        return;
      if (target.dataset.dragged === "true" || target.dataset.moved === "true")
        return;
      let activityValue =
        target.dataset.activityV9 ||
        target.dataset.v5362Activity ||
        target.dataset.v5360StageCard ||
        target.dataset.v5356StageActivity ||
        target.dataset.activityDetail ||
        "";
      if (target.matches("[data-activity-open]"))
        activityValue =
          activityCatalog[Number(target.dataset.activityOpen)]?.name ||
          activityValue;
      if (!activityValue && target.matches("[data-agenda-item]"))
        activityValue =
          target.querySelector(".agenda-item-copy strong")?.textContent || "";
      if (!activityValue && target.matches("[data-activity-card]"))
        activityValue = target.querySelector("h3,h2,strong")?.textContent || "";
      if (!activityValue) return;
      const stageValue =
        target.dataset.stage ||
        target.closest("[data-stage]")?.dataset.stage ||
        "";
      event.preventDefault();
      event.stopImmediatePropagation();
      window.location.assign(
        workbenchActivityRouteV1(activityValue, stageValue),
      );
    },
    true,
  );
};
// Compatibilidade de marca para extensões legadas: somente texto e campos
// apresentados ao usuário são normalizados; namespaces, chaves e APIs ficam intactos.
const ALIANCA_PARK_BRAND = "Aliança Park";
const normalizeAliancaParkBrand = (root = document) => {
  if (!root?.createTreeWalker) return;
  const walker = root.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);
  for (const node of textNodes) {
    if (node.parentElement?.closest("script,style")) continue;
    if (/\bbelavista\b/i.test(node.nodeValue || ""))
      node.nodeValue = node.nodeValue.replace(
        /\bbelavista\b/gi,
        ALIANCA_PARK_BRAND,
      );
  }
  root
    .querySelectorAll?.("[value],[title],[placeholder],[aria-label],[content]")
    .forEach((element) => {
      if (element.closest("script,style")) return;
      for (const attribute of [
        "value",
        "title",
        "placeholder",
        "aria-label",
        "content",
      ]) {
        const value = element.getAttribute(attribute);
        if (!value || !/(?<![-_.])belavista(?![-_.])/i.test(value)) continue;
        if (
          attribute === "placeholder" &&
          !/empreendimento\s+belavista/i.test(value)
        )
          continue;
        element.setAttribute(
          attribute,
          value.replace(/\bbelavista\b/gi, ALIANCA_PARK_BRAND),
        );
      }
    });
};
if (globalThis.MutationObserver && globalThis.document?.documentElement) {
  const brandObserver = new MutationObserver((records) =>
    records.forEach((record) => {
      for (const node of record.addedNodes) {
        if (node.nodeType === Node.ELEMENT_NODE)
          normalizeAliancaParkBrand(node);
        else if (
          node.nodeType === Node.TEXT_NODE &&
          /\bbelavista\b/i.test(node.nodeValue || "")
        )
          node.nodeValue = node.nodeValue.replace(
            /\bbelavista\b/gi,
            ALIANCA_PARK_BRAND,
          );
      }
    }),
  );
  brandObserver.observe(document.documentElement, {
    subtree: true,
    childList: true,
  });
  queueMicrotask(() => normalizeAliancaParkBrand(document));
}
const notify = (message, tone = "info") => {
  let host = document.querySelector(".app-main");
  if (!host) return;
  let toast = host.querySelector(".action-toast");
  if (!toast) {
    toast = document.createElement("div");
    toast.className = "action-toast";
    host.appendChild(toast);
  }
  toast.dataset.tone = tone;
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(toast._timer);
  toast._timer = setTimeout(() => toast.classList.remove("show"), 2800);
};
