    const rough =
      surface === "cobble"
        ? ".94 + .055*bvNoise(vBelavistaSurfacePos*3.4)"
        : surface === "gravel"
          ? ".97 + .025*bvNoise(vBelavistaSurfacePos*4.8)"
          : surface === "grass"
            ? ".965 + .03*bvNoise(vBelavistaSurfacePos*4.6)"
            : surface === "rubber"
              ? ".86 + .09*bvNoise(vBelavistaSurfacePos*7.0)"
              : surface === "wood"
