      dy = Number(y) - Number(terrain.position.y || 0),
      angle = -(Number(terrain.rotation?.z) || 0),
      c = Math.cos(angle),
      s = Math.sin(angle),
      localX = dx * c - dy * s,
      localY = dx * s + dy * c;
