        for (const [dx, dy] of [
          [-1, 0],
          [1, 0],
          [0, -1],
          [0, 1],
        ])
          if (cellByKey.get(`${item.gx + dx}:${item.gy + dy}`)?.candidate)
            neighbours++;
        item.neighbours = neighbours;
        item.score += neighbours * 17;
