      return false;
    const canvas = this.querySelector(".three-overlay"),
      width = Math.max(
        1,
        canvas?.clientWidth || this.clientWidth || window.innerWidth,
      ),
      height = Math.max(
        1,
        canvas?.clientHeight || this.clientHeight || window.innerHeight,
      );
