      this.style.setProperty("--public-focus-y", `${centerY.toFixed(1)}px`);
      this.style.setProperty("--public-focus-w", `${frameWidth.toFixed(1)}px`);
      this.style.setProperty("--public-focus-h", `${frameHeight.toFixed(1)}px`);
