    this.dataset.mapPrintCamera = `${Math.round(Number(this.sceneManualZoom || 0) * 100)}% · ${Math.round(Number(this.sceneManualRotation || 0))}° · tilt ${Math.round(Number(this._sceneVisual?.tilt || 0))}°`;
