// camadas do mapa: somente um resumo fica ativo por vez.
const mapFilterSelectionKeyV1 = (state) => {
  const allowed = new Set(
    dashboardFiltersForModeV1(state?.dashboardMode).map((item) => item[0]),
  );
  const candidates = [
    state?.mapFilterWidget,
    state?.mapFilter,
    ...(Array.isArray(state?.mapFilters)
      ? state.mapFilters.slice().reverse()
      : []),
  ];
  return candidates.find((key) => allowed.has(key)) || null;
};
