const mapProgressSummaryMarkupV1 = (state) => {
  const areas = Array.isArray(state.mapProgressSelection)
    ? state.mapProgressSelection
    : [];
  const selectedStage = String(state.selectedStage ?? "");
  const stages = Array.isArray(demoData.activities) ? demoData.activities : [];
  const areaMarkup = areas.length
    ? `<div class="map-filter-progress-areas">${areas
        .slice(0, 5)
        .map((area) => `<span>${esc(area.label || area.partId)}</span>`)
        .join(
          "",
        )}${areas.length > 5 ? `<span>+${areas.length - 5} áreas</span>` : ""}</div>`
    : '<p class="map-filter-progress-empty">Nenhuma área poligonal selecionada. Clique em “Selecionar áreas” e marque um ou mais polígonos no mapa.</p>';
  const stageMarkup = stages
    .map((stage, index) => {
      const progress = Math.max(0, Math.min(100, Number(stage.progress) || 0));
      const active = String(stage.id) === selectedStage;
      const stateLabel =
        progress >= 100
          ? "Concluída"
          : progress > 0
            ? "Em andamento"
            : "Planejada";
      return `<div class="map-filter-progress-stage ${active ? "selected" : ""}"><div><span>${String(index + 1).padStart(2, "0")}</span><b>${esc(stage.name)}</b><em>${stateLabel}</em></div><i><strong style="width:${progress}%"></strong></i><small>${progress}%</small></div>`;
    })
    .join("");
  return `<section class="map-filter-progress-context" data-map-progress-context><header><span>ÁREAS POLIGONAIS SELECIONADAS</span><b>${areas.length}</b></header>${areaMarkup}<div class="map-filter-progress-list" aria-label="Progresso das etapas">${stageMarkup}</div><div class="map-filter-progress-actions"><button type="button" class="ghost" data-map-progress-start>${ico("scan-search")} ${areas.length ? "Adicionar áreas" : "Selecionar áreas"}</button>${areas.length ? `<button type="button" class="primary" data-map-progress-entry>${ico("clipboard-pen-line")} Registrar avanço</button><button type="button" class="map-filter-progress-clear" data-map-progress-clear>Limpar</button>` : ""}</div></section>`;
};
const mapFilterSummaryMarkupV1 = (key, state) => {
  const filter =
      dashboardFilterForModeV1(key, state.dashboardMode) || dashboardFilters[0],
    status = highlightStatus[key] || highlightStatus.execution;
  if (!filter) return "";
  const metrics = mapFilterSummaryMetricsV1(key, state);
  return `<aside class="map-filter-summary-widget" id="map-filter-summary-${esc(key)}" data-map-summary-widget data-map-summary-key="${esc(key)}" aria-live="polite"><header><div><span>RESUMO DA CAMADA</span><h3>${ico(filter[2])} ${esc(filter[1])}</h3></div><button type="button" data-map-widget-close aria-label="Fechar resumo de ${esc(filter[1])}">×</button></header><div class="map-filter-summary-metrics">${metrics.map(([label, value, detail]) => `<div><small>${esc(label)}</small><b>${esc(value)}</b><span>${esc(detail)}</span></div>`).join("")}</div><p>${esc(status.detail)}</p>${key === "progress" ? mapProgressSummaryMarkupV1(state) : ""}<footer><small>${esc(status.next)}</small><button type="button" data-map-widget-context="${esc(status.view)}">Abrir contexto ${ico("arrow-up-right")}</button></footer></aside>`;
};

const syncDashboardMapWidgetSmokeV1 = (active) => {
  document
    .querySelectorAll(
      'map-scene[data-persistent-map="true"],map-scene[data-dashboard-operational-map]',
    )
    .forEach((map) =>
      map.toggleAttribute("data-map-widgets-open", Boolean(active)),
    );
};

export class MapFilterRail extends HTMLElement {
  connectedCallback() {
    this._mapProgressSelectionSignature = "";
    this._mapProgressSelectionUnsubscribe = appStore.subscribe((state) => {
      const signature = JSON.stringify(state.mapProgressSelection || []);
      if (signature !== this._mapProgressSelectionSignature) this.render();
    });
    this.render();
  }
  disconnectedCallback() {
    this._mapProgressSelectionUnsubscribe?.();
    this._mapProgressSelectionUnsubscribe = null;
  }
  render() {
    const state = appStore.get(),
      mode = dashboardModeKeyV1(state.dashboardMode),
      filters = dashboardFiltersForModeV1(mode),
      selectedKey = mapFilterSelectionKeyV1(state),
      active = selectedKey ? [selectedKey] : [],
      widgetKey = filters.some((item) => item[0] === state.mapFilterWidget)
        ? state.mapFilterWidget
        : null,
      modeMeta = dashboardModes[mode];
    syncDashboardMapWidgetSmokeV1(Boolean(widgetKey));
    const socialContactBar =
      mode === "social"
        ? `<div class="dashboard-social-contact-bar" aria-label="Highlights por contato da conversa"><span>DESTAQUE DA CONVERSA</span><div>${[
            ["social-instagram", "Instagram"],
            ["social-personal", "Pessoal"],
            ["social-clients", "Cliente"],
            ["social-brokers", "Corretor"],
            ["social-staff-operating", "Encarregado · operando"],
            ["social-staff-services", "Serviços"],
            ["social-staff-planned", "Planejados"],
          ]
            .map(
              ([key, label]) =>
                `<button type="button" data-map-filter="${key}" class="${active.includes(key) ? "active" : ""}" aria-pressed="${active.includes(key)}">${esc(label)}</button>`,
            )
            .join("")}</div></div>`
        : "";
    this._mapProgressSelectionSignature = JSON.stringify(
      state.mapProgressSelection || [],
    );
    this.dataset.dashboardMode = mode;
    this.innerHTML = `${widgetKey ? mapFilterSummaryMarkupV1(widgetKey, state) : ""}<div class="map-filter-rail-head"><span>${esc(modeMeta.label.toUpperCase())} · WIDGETS DO MAPA</span><small>${esc(modeMeta.description)} · selecione um item para abrir seu resumo e destacar os lotes correspondentes</small><button type="button" class="map-filter-clear" data-map-filter-clear ${active.length ? "" : "disabled"}>Limpar</button></div><div class="map-filter-rail-items">${filters.map(([key, label, icon]) => `<button type="button" class="map-filter-chip ${active.includes(key) ? "active" : ""}" data-map-filter="${key}" aria-pressed="${active.includes(key)}" aria-expanded="${widgetKey === key}">${ico(icon)}<span>${label}</span></button>`).join("")}</div>${socialContactBar}<div class="map-filter-rail-status" aria-live="polite">${selectedKey ? `Exibição ativa · ${esc(filters.find((item) => item[0] === selectedKey)?.[1] || selectedKey)}` : "Nenhum widget selecionado"}${widgetKey ? ` · resumo de ${esc(filters.find((item) => item[0] === widgetKey)?.[1] || widgetKey)}` : ""}</div>`;
    this.querySelectorAll("[data-map-filter]").forEach((button) =>
      button.addEventListener("click", () =>
        this.select(button.dataset.mapFilter),
      ),
    );
    this.querySelector("[data-map-filter-clear]")?.addEventListener(
      "click",
      () => this.clear(),
    );
    this.querySelector("[data-map-progress-start]")?.addEventListener(
      "click",
      (event) => {
        event.preventDefault();
        event.stopPropagation();
        const map =
          document.querySelector("map-scene[data-dashboard-operational-map]") ||
          document.querySelector("map-scene:not([compact])");
        map?.setMapSelectionMode("progress");
        appStore.set({
          mapFilterWidget: "progress",
          lastAction: "Ativou seleção de áreas para leitura de progresso",
        });
      },
    );
    this.querySelector("[data-map-progress-clear]")?.addEventListener(
      "click",
      (event) => {
        event.preventDefault();
        event.stopPropagation();
        const map =
          document.querySelector("map-scene[data-dashboard-operational-map]") ||
          document.querySelector("map-scene:not([compact])");
        map?.clearProgressAreaSelectionV1(true);
      },
    );
    this.querySelector("[data-map-progress-entry]")?.addEventListener(
      "click",
      (event) => {
        event.preventDefault();
        event.stopPropagation();
        const map =
          document.querySelector("map-scene[data-dashboard-operational-map]") ||
          document.querySelector("map-scene:not([compact])");
        const parts = map?.progressSelectionParts?.length
          ? map.progressSelectionParts
          : map?.progressAreaPartsFromStoreV1?.();
        if (parts?.length) map.renderProgressSelectionPanel(parts);
        else map?.setMapSelectionMode("progress");
      },
    );
    this.querySelectorAll(
      "[data-map-progress-start],[data-map-progress-clear],[data-map-progress-entry]",
    ).forEach((button) => {
      button.dataset.mapProgressActionBound = "true";
    });
    this.querySelector("[data-map-widget-close]")?.addEventListener(
      "click",
      (event) => {
        event.stopPropagation();
        const key = event.currentTarget.closest("[data-map-summary-widget]")
            ?.dataset.mapSummaryKey,
          filter =
            dashboardFilterForModeV1(key, state.dashboardMode) ||
            dashboardFilters[0];
        appStore.set({
          mapFilters: [],
          mapFilter: null,
          mapFilterWidget: null,
          lastAction: `Fechou resumo de ${filter[1] || "camada"}`,
        });
        document
          .querySelectorAll("map-filter-rail")
          .forEach((rail) => rail.render());
      },
    );
    this.querySelector("[data-map-widget-context]")?.addEventListener(
      "click",
      (event) => {
        event.preventDefault();
        event.stopImmediatePropagation();
        const button = event.currentTarget,
          summary = button.closest("[data-map-summary-widget]"),
          key = summary?.dataset.mapSummaryKey;
        const filter =
            dashboardFilterForModeV1(key, state.dashboardMode) ||
            dashboardFilters[0],
          nextView = button.dataset.mapWidgetContext || "map";
        if (key === "progress") {
          const map =
            document.querySelector(
              "map-scene[data-dashboard-operational-map]",
            ) || document.querySelector("map-scene:not([compact])");
          map?.setMapSelectionMode("progress");
        }
        appStore.set({
          view: nextView,
          mapFilterWidget: key,
          lastAction: `Abriu contexto de ${filter[1]} no mapa`,
        });
      },
    );
    window.lucide?.createIcons();
  }
  select(key) {
    const state = appStore.get(),
      filter = dashboardFilterForModeV1(key, state.dashboardMode);
    if (!filter) return;
    appStore.set({
      mapFilters: [key],
      mapFilter: key,
      mapFilterWidget: key,
      lastAction: `Exibiu resumo de ${filter[1]}`,
    });
    const map =
      document.querySelector('map-scene[data-persistent-map="true"]') ||
      document.querySelector("map-scene[data-dashboard-operational-map]");
    map?.applyDashboardModeHighlightV1?.(key);
    document
      .querySelectorAll("map-filter-rail")
      .forEach((rail) => rail.render());
  }
  clear() {
    appStore.set({
      mapFilters: [],
      mapFilter: null,
      mapFilterWidget: null,
      lastAction: "Limpou o resumo selecionado",
    });
    const map =
      document.querySelector('map-scene[data-persistent-map="true"]') ||
      document.querySelector("map-scene[data-dashboard-operational-map]");
    map?.clearDashboardModeHighlightV1?.();
    document
      .querySelectorAll("map-filter-rail")
      .forEach((rail) => rail.render());
  }
}
if (!customElements.get("map-filter-rail"))
  customElements.define("map-filter-rail", MapFilterRail);

// A página pode manter um map-filter-rail criado por uma versão anterior do
// módulo durante uma navegação SPA. O complemento abaixo reidrata somente o
// resumo de Progresso, sem tentar redefinir o custom element já registrado.
const refreshProgressSummaryFallbackV1 = () => {
  const state = appStore.get();
  if (state.mapFilterWidget !== "progress") return;
  document
    .querySelectorAll('[data-map-summary-key="progress"]')
    .forEach((widget) => {
      widget.querySelector("[data-map-progress-context]")?.remove();
      const footer = widget.querySelector("footer");
      if (footer)
        footer.insertAdjacentHTML(
          "beforebegin",
          mapProgressSummaryMarkupV1(state),
        );
      else
        widget.insertAdjacentHTML(
          "beforeend",
          mapProgressSummaryMarkupV1(state),
        );
      window.lucide?.createIcons?.();
    });
};
if (!globalThis.__belavistaProgressSummaryFallbackV1) {
  globalThis.__belavistaProgressSummaryFallbackV1 = true;
  appStore.subscribe(refreshProgressSummaryFallbackV1);
  document.addEventListener(
    "click",
    (event) => {
      const button = event.target.closest?.(
        "[data-map-progress-start],[data-map-progress-clear],[data-map-progress-entry]",
      );
      if (!button || button.dataset.mapProgressActionBound === "true") return;
      event.preventDefault();
      event.stopPropagation();
      const map =
        document.querySelector("map-scene[data-dashboard-operational-map]") ||
        document.querySelector("map-scene:not([compact])");
      if (button.hasAttribute("data-map-progress-start")) {
        map?.setMapSelectionMode("progress");
        appStore.set({
          mapFilterWidget: "progress",
          lastAction: "Ativou seleção de áreas para leitura de progresso",
        });
      } else if (button.hasAttribute("data-map-progress-clear")) {
        map?.clearProgressAreaSelectionV1?.(true);
      } else {
        const parts = map?.progressSelectionParts?.length
          ? map.progressSelectionParts
          : map?.progressAreaPartsFromStoreV1?.();
        if (parts?.length) map.renderProgressSelectionPanel(parts);
        else map?.setMapSelectionMode("progress");
      }
    },
    true,
  );
}
refreshProgressSummaryFallbackV1();

