// BELAVISTA_COMMERCIAL_PAGES_V7
ViewLayer.prototype.brokers = function () {
  const deals = [
    ...commissionDeals,
    ...(appStore.get().commissionEntries || []),
  ];
  const statusFor = (person) => {
    const owned = deals.filter((item) => item.profile === person.id);
    if (
      owned.some(
        (item) => item.status === "Proposta" || item.status === "Em análise",
      )
    )
      return ["Em negociação", "attention"];
    if (owned.some((item) => item.status === "Reserva"))
      return ["Acompanhamento", "info"];
    return ["Ativo", "success"];
  };
  queueMicrotask(() => this.bindCommercialPagesV7?.());
  const period = appStore.get().reportPeriod || "monthly";
  const periodLabels = {
      monthly: "Mensal",
      annual: "Anual",
      cumulative: "Acumulado",
    },
    periodLabel = periodLabels[period] || periodLabels.monthly;
  return `<section class="v7-brokers-page"><header class="v7-page-head"><div><span class="activity-kind">GESTÃO COMERCIAL</span><h1>Corretores</h1><p>Listagem operacional de situação, carteira, contatos e vínculos comerciais.</p></div><button type="button" class="toolbar-primary" data-v7-brokers-export>${ico("download")} Exportar planilha</button></header><nav class="v7-period-tabs" aria-label="Período dos repasses">${Object.entries(
    periodLabels,
  )
    .map(
      ([id, label]) =>
        `<button type="button" class="${period === id ? "active" : ""}" data-v7-period="${id}">${label}</button>`,
    )
    .join(
      "",
    )}</nav><div class="v7-page-kpis"><article><small>Corretores ativos</small><b>${commissionProfiles.length}</b><span>carteiras acompanhadas</span></article><article><small>Negócios vinculados</small><b>${deals.length}</b><span>${periodLabel}</span></article><article><small>Vendas informadas</small><b>${commissionProfiles.reduce((sum, p) => sum + p.sales, 0)}</b><span>ciclo demonstrativo</span></article><article><small>Comissão acumulada</small><b>${formatBRL(deals.reduce((sum, item) => sum + brlToNumber(item.commission), 0))}</b><span>lançamentos visíveis</span></article></div><section class="v7-sheet"><header><div><span class="activity-kind">SITUAÇÃO DA EQUIPE · ${periodLabel.toUpperCase()}</span><h2>Carteiras e disponibilidade</h2></div><label>Buscar<input data-v7-broker-search placeholder="Nome, CRECI, lote..."></label></header><div class="v7-broker-table-wrap"><table><thead><tr><th>Corretor</th><th>CRECI</th><th>Situação</th><th>Carteira</th><th>Conversão</th><th>Lotes</th><th>Contato</th></tr></thead><tbody>${commissionProfiles
    .map((person) => {
      const [status, tone] = statusFor(person);
      return `<tr data-v7-broker-row data-search="${esc((person.name + " " + person.creci + " " + person.lots.join(" ")).toLowerCase())}"><td><span class="v7-person-cell"><i class="commission-avatar" style="background:${person.avatar}">${person.initials}</i><span><b>${esc(person.name)}</b><small>${esc(person.role)}</small></span></span></td><td>${esc(person.creci)}</td><td><span class="v7-status ${tone}">${status}</span></td><td><b>${person.sales} vendas</b><small>${esc(person.commission)}</small></td><td>${esc(person.conversion)}</td><td>${person.lots.map((lot) => `<em>${esc(lot)}</em>`).join(" ")}</td><td><div class="v7-row-actions"><a href="https://wa.me/${esc(person.phone)}" target="_blank" rel="noopener">${ico("message-circle")} WhatsApp</a><button type="button" data-v7-open-broker="${esc(person.id)}">Carteira</button></div></td></tr>`;
    })
    .join("")}</tbody></table></div></section></section>`;
};

ViewLayer.prototype.finance = function () {
  syncLiveSystemReportV1(appStore.get());
  const financial = reportCatalog.filter(
    (report) => report.family === "Financeiro",
  );
  const selected =
    financial.find((report) => report.id === appStore.get().reportType) ||
    financial[0];
  const moneyRows = selected?.rows || [];
  queueMicrotask(() => this.bindCommercialPagesV7?.());
  return `<section class="v7-finance-page"><header class="v7-page-head"><div><span class="activity-kind">GESTÃO FINANCEIRA</span><h1>Balanços e planilhas</h1><p>Leitura consolidada de orçamento, caixa, realizado, compromissos e projeções.</p></div><button type="button" class="toolbar-primary" data-v7-finance-export>${ico("download")} Exportar planilha</button></header><nav class="v7-fin-tabs">${financial.map((report) => `<button type="button" class="${report.id === selected?.id ? "active" : ""}" data-v7-fin-report="${esc(report.id)}">${ico(report.icon || "file-spreadsheet")}<span>${esc(report.label)}</span></button>`).join("")}</nav>${selected ? `<div class="v7-page-kpis">${selected.metrics.map(([label, value, sub]) => `<article><small>${esc(label)}</small><b>${esc(value)}</b><span>${esc(sub)}</span></article>`).join("")}</div><section class="v7-sheet"><header><div><span class="activity-kind">${esc(selected.family)}</span><h2>${esc(selected.label)}</h2><p>${esc(selected.description)}</p></div><small>${esc(selected.source || "")}</small></header><div class="v7-fin-table-wrap"><table><thead><tr>${selected.columns.map((col) => `<th>${esc(col)}</th>`).join("")}</tr></thead><tbody>${moneyRows.map((row) => `<tr>${row.map((cell) => `<td>${esc(cell)}</td>`).join("")}</tr>`).join("")}</tbody></table></div></section>` : '<div class="empty-data">Nenhuma planilha financeira disponível.</div>'}</section>`;
};

ViewLayer.prototype.bindCommercialPagesV7 = function () {
  const root = this.querySelector(".v7-brokers-page,.v7-finance-page");
  if (!root || root.dataset.v7Bound) return;
  root.dataset.v7Bound = "1";
  if (root.matches(".v7-finance-page")) {
    const exportButton = root.querySelector("[data-v7-finance-export]");
    exportButton?.insertAdjacentHTML("afterend", '<button type="button" class="toolbar-action" data-v7-finance-print>Imprimir</button>');
    root.querySelector("[data-v7-finance-print]")?.addEventListener("click", () => window.print());
  }
  root
    .querySelector("[data-v7-broker-search]")
    ?.addEventListener("input", (event) => {
      const q = event.target.value.toLowerCase();
      root
        .querySelectorAll("[data-v7-broker-row]")
        .forEach((row) => (row.hidden = !row.dataset.search.includes(q)));
    });
  root.querySelectorAll("[data-v7-open-broker]").forEach((button) =>
    button.addEventListener("click", () =>
      appStore.set({
        view: "commissions",
        selectedCommissionProfile: button.dataset.v7OpenBroker,
        selectedCommissionContract: null,
        lastAction: "Abriu carteira do corretor",
      }),
    ),
  );
  root.querySelectorAll("[data-v7-fin-report]").forEach((button) =>
    button.addEventListener("click", () =>
      appStore.set({
        view: "finance",
        reportFamily: "Financeiro",
        reportType: button.dataset.v7FinReport,
        lastAction: "Abriu planilha financeira",
      }),
    ),
  );
  root.querySelectorAll("[data-v7-period]").forEach((button) =>
    button.addEventListener("click", () =>
      appStore.set({
        reportPeriod: button.dataset.v7Period,
        lastAction: `Alterou período para ${button.textContent.trim()}`,
      }),
    ),
  );
  root
    .querySelector("[data-v7-brokers-export]")
    ?.addEventListener("click", () =>
      downloadCsv(
        "corretores.csv",
        ["Corretor", "CRECI", "Vendas", "Comissão", "Conversão", "Lotes"],
        commissionProfiles.map((p) => [
          p.name,
          p.creci,
          p.sales,
          p.commission,
          p.conversion,
          p.lots.join(" | "),
        ]),
      ),
    );
  root
    .querySelector("[data-v7-finance-export]")
    ?.addEventListener("click", () => {
      syncLiveSystemReportV1(appStore.get());
      const report =
        reportCatalog.find((r) => r.id === appStore.get().reportType) ||
        reportCatalog.find((r) => r.family === "Financeiro");
      if (report) downloadCsv(`${report.id}.csv`, report.columns, report.rows);
    });
  window.lucide?.createIcons();
};

// Diário seguro: a tela de entrada não monta catálogos, filtros e imagens em
// lote. Esses detalhes permanecem acessíveis ao editar um registro, mas a
// navegação sempre chega primeiro a uma lista leve e responsiva.
ViewLayer.prototype.records = function () {
  const state = appStore.get();
  const records = Array.isArray(state.records) ? state.records : [];
  const rows = records
    .slice()
    .reverse()
    .slice(0, 250)
    .map(
      (record) =>
        `<article class="record-card"><div class="record-main"><span class="record-id">${esc(record.id || "REGISTRO")}</span><strong>${esc(record.atividade || "Atividade operacional")}</strong><small>${esc(record.data || "Sem data")} · ${esc(record.hora || "")} · ${esc(record.responsavel || "A definir")}</small><small>${esc(record.detalhes || "Sem detalhe informado")}</small></div><span class="record-status">${esc(record.status || "Pendente")}</span></article>`,
    )
    .join("");
  return `<div class="records-page"><div class="records-shell"><div class="records-head"><div><span class="activity-kind">HISTÓRICO OPERACIONAL</span><h1>Registros</h1><p>Consulta completa dos apontamentos, medições e evidências já registrados.</p></div></div><section class="records-list records-history"><div class="records-list-head"><b>${records.length} registros no histórico</b><small>ordem do mais recente para o mais antigo</small></div>${rows || '<div class="empty-records">Nenhum registro cadastrado.</div>'}</section></div></div>`;
};

