const bindMasterCashAndIntegrations = ViewLayer.prototype.bind;
ViewLayer.prototype.bind = function () {
  bindMasterCashAndIntegrations.call(this);
  const form = this.querySelector("[data-integration-form]");
  form?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const raw = Object.fromEntries(new FormData(form));
    const looksLikeGithubPat = (value) =>
      /^(?:github_pat_|ghp_|gho_|ghu_|ghs_|ghr_)[A-Za-z0-9_]+$/.test(
        String(value || "").trim(),
      );
    const data = Object.fromEntries(
      Object.entries(raw).filter(([key, value]) => {
        if (looksLikeGithubPat(value)) return false;
        return !/^(?:pat|githubPat|github_pat|githubToken|github_token)$/i.test(
          key,
        );
      }),
    );
    data.workerSecretGithubPat = "GITHUB_PAT";
    data.autoNotify = form.elements.autoNotify.checked;
    data.stageProfiles = {
      ...(readIntegrationSettings().stageProfiles || {}),
      ...(appStore.get().integrationSettings?.stageProfiles || {}),
    };
    localStorage.setItem(INTEGRATION_SETTINGS_KEY, JSON.stringify(data));

    // Não publica o formulário inteiro no appStore: ViewLayer assina o store
    // com render() completo. Salvar um segredo/configuração não deve reconstruir
    // toda a interface nem multiplicar bindings/subscrições.
    document.dispatchEvent(
      new CustomEvent("belavista:integrations-saved", {
        detail: { settings: data },
      }),
    );
    notify(
      "Configurações salvas. O PAT permanece somente no segredo GITHUB_PAT do Worker.",
      "success",
    );
  });
  this.querySelector("[data-register-device]")?.addEventListener(
    "click",
    async (event) => {
      const button = event.currentTarget,
        status = this.querySelector("[data-device-status]"),
        actor = appStore.get().currentActor;
      button.disabled = true;
      status.textContent =
        "Solicitando permissão e conectando este dispositivo ao canal em tempo real…";
      try {
        const result = await registerOperationalDevice(actor);
        await this.connectOperationalNotifications(true);
        status.textContent = result.pushEnabled
          ? "Dispositivo registrado no Realtime Database com push habilitado."
          : "Dispositivo registrado no Realtime Database; o push pode ser ativado depois com a chave VAPID.";
        notify(
          "Dispositivo vinculado ao canal operacional em tempo real.",
          "success",
        );
      } catch (error) {
        button.disabled = false;
        status.textContent = error.message;
        notify("Não foi possível ativar notificações.", "warning");
      }
    },
  );
  this.querySelector("[data-calibration-form]")?.addEventListener(
    "submit",
    async (event) => {
      event.preventDefault();
      const form = event.currentTarget,
        status = form.querySelector("[data-calibration-status]"),
        parseMoney = (value) =>
          Math.round(
            Number(
              String(value || "")
                .replace(/\./g, "")
                .replace(",", "."),
            ) * 100,
          ) || 0,
        stages = [...form.querySelectorAll("[data-calibration-stage]")].map(
          (row) => ({
            key: row.dataset.calibrationStage,
            budgetCents: parseMoney(
              row.querySelector('[name="budgetCents"]').value,
            ),
            priority: Number(row.querySelector('[name="priority"]').value) || 0,
            dependsOn: row
              .querySelector('[name="dependsOn"]')
              .value.split(",")
              .filter(Boolean),
          }),
        ),
        payload = {
          reserveCents: parseMoney(form.elements.reserve.value),
          dependencyProgress: Number(form.elements.dependencyProgress.value),
          notificationCooldownMinutes: Number(
            form.elements.notificationCooldownMinutes.value,
          ),
          stages,
        };
      status.textContent = "Validando relações e criando uma nova versão…";
      try {
        const response = await apiFetch("/api/calibrations", {
            method: "PUT",
            headers: operationalHeaders({ "Content-Type": "application/json" }),
            body: JSON.stringify(payload),
          }),
          result = await response.json();
        if (!response.ok)
          throw new Error(result.error || `HTTP ${response.status}`);
        appStore.set({
          systemCalibration: result.calibration,
          operationalState: result.operational,
          lastAction: `Administrador publicou calibração ${result.calibration.version}`,
        });
        await this.runOperationalLoop("calibration.changed");
        notify("Calibração publicada e caixa redistribuído.", "success");
      } catch (error) {
        status.textContent = error.message;
        notify("Calibração não foi alterada.", "warning");
      }
    },
  );
  this.querySelectorAll("[data-lead-card]").forEach((button) => {
    const reservation = (appStore.get().publicReservations || []).find(
      (item) => item.id === button.dataset.leadCard,
    );
    if (reservation && reservation.files?.length) {
      button.textContent =
        reservation.status === "Reserva validada"
          ? "Documentos validados"
          : "Validar documentos e reserva";
      button.disabled = reservation.status === "Reserva validada";
      button.addEventListener("click", async () => {
        if (
          !confirm(
            `Confirmar que os documentos de ${reservation.client} foram conferidos e validar a reserva do lote ${reservation.lot}?`,
          )
        )
          return;
        button.disabled = true;
        try {
          const response = await apiFetch(
            `/api/commercial-sales/${encodeURIComponent(reservation.id)}`,
            {
              method: "PUT",
              headers: operationalHeaders({
                "Content-Type": "application/json",
              }),
              body: JSON.stringify({
                status: "Reserva validada",
                documentValidation: true,
                notes: `${reservation.notes || ""}; Documentos conferidos em ${new Date().toLocaleString("pt-BR")}`,
              }),
            },
          );
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          notify("Documentos confirmados; reserva validada.", "success");
          await this.loadCommercialReservations();
        } catch (error) {
          button.disabled = false;
          notify("Não foi possível validar a reserva.", "warning");
          console.warn(error);
        }
      });
    } else
      button.addEventListener("click", () => {
        document
          .querySelector('.lead-conversation-widget input[name="message"]')
          ?.focus();
        notify(`Atendimento ${button.dataset.leadCard} selecionado.`);
      });
  });
};

