// STAGE_FOREMEN_TAB_V1: leitura contextual dos responsáveis da etapa em foco.
// O cadastro completo permanece em Pessoal; aqui a etapa mostra somente quem
// está ligado àquela frente e qual é a responsabilidade operacional.
const stageForemenMembersV1 = (stage, state) => {
  const contacts = Array.isArray(state.foremenContacts)
    ? state.foremenContacts.filter((item) =>
        (item.stages || []).includes(stage.key),
      )
    : [];
  if (contacts.length) return contacts;
  const modeled = (personnelModel.members || []).filter(
    (item) => item.team === stage.key || item.stage === stage.key,
  );
  if (modeled.length) return modeled;
  return [
    {
      id: `stage-owner-${stage.key}`,
      name: stage.owner || "Responsável a definir",
      role: "Encarregado da etapa",
      status: "Aguardando vínculo",
      skills: stage.production?.unit ? [stage.production.unit] : [],
    },
  ];
};

ViewLayer.prototype.foremen = function () {
  const state = appStore.get(),
    stage = extensionStage(),
    members = stageForemenMembersV1(stage, state),
    live = stageV9LiveFor(stage),
    active = members.filter((item) =>
      /campo|operando|disponível|disponivel/i.test(item.status || ""),
    ).length,
    cards = members
      .map(
        (member, index) =>
          `<article class="stage-foreman-card"><header><span class="stage-foreman-avatar">${esc(
            String(member.name || "?")
              .trim()
              .slice(0, 2)
              .toUpperCase(),
          )}</span><div><h3>${esc(member.name || "Responsável a definir")}</h3><p>${esc(member.role || "Encarregado")}</p></div><span class="stage-foreman-status ${/campo|operando/i.test(member.status || "") ? "live" : ""}">${esc(member.status || "Sem status")}</span></header><dl><div><dt>Vínculo na etapa</dt><dd>${esc(stage.name)}</dd></div><div><dt>Atividades acompanhadas</dt><dd>${esc(String(member.activityCount ?? (index === 0 ? live.progress || 0 : 0)))} registros</dd></div></dl><footer><span>${(member.skills || []).map((skill) => esc(skill)).join(" · ") || "Atribuição operacional em definição"}</span><button type="button" data-view="personnel">Abrir cadastro ${ico("arrow-up-right")}</button></footer></article>`,
      )
      .join("");
  return `<section class="stage-foremen-page stage-extension-page"><div class="extension-head"><div><span class="activity-kind">ETAPA EM FOCO · RESPONSÁVEIS</span><h1>Por encarregados</h1><p>Veja os encarregados vinculados à etapa <strong>${esc(stage.name)}</strong>, suas atividades e a situação de campo.</p></div><div class="stage-foremen-head-meta"><span>${members.length} responsável${members.length === 1 ? "" : "es"}</span><small>${active} em acompanhamento ou disponibilidade</small></div></div><section class="stage-foremen-summary"><article><small>ETAPA</small><b>${esc(stage.name)}</b><span>${esc(stage.production?.unit || "Unidade de produção")}</span></article><article><small>AVANÇO</small><b>${Number(live.progress) || 0}%</b><span>${esc(live.status || "Em acompanhamento")}</span></article><article><small>RESPONSÁVEIS</small><b>${members.length}</b><span>vínculos encontrados</span></article><article><small>PRÓXIMA AÇÃO</small><b>${esc(stage.nextAction || "Registrar avanço")}</b><span>orientação da etapa</span></article></section><section class="stage-foremen-list"><header><div><span class="activity-kind">RESPONSÁVEIS DA FRENTE</span><h2>Equipe por encarregado</h2><p>A visão acompanha a etapa selecionada na barra acima e não altera o cadastro central.</p></div><span>${members.length} vínculo${members.length === 1 ? "" : "s"}</span></header><div>${cards}</div></section></section>`;
};

// STAGE_SUBPAGE_MAP_SHELL_V1: todas as superfícies da etapa compartilham o
// mesmo cabeçalho visual. O mapa entra no HTML inicial de cada subpágina;
// assim a barra de abas só alterna o conteúdo abaixo dela.
const stageSubpageMapShellV1 = (html) => {
  if (!html || html.includes("data-stage-header-3d")) return html;
  return html.replace(
    '<div class="extension-head">',
    `${stageHeader3DMarkup(extensionStage())}<div class="extension-head">`,
  );
};
["agenda", "pert", "actions", "raci", "raid", "foremen"].forEach((view) => {
  const base = ViewLayer.prototype[view];
  if (typeof base !== "function") return;
  ViewLayer.prototype[view] = function (...args) {
    return stageSubpageMapShellV1(base.apply(this, args) || "");
  };
});

// STAGE_VIEW_TABS_EVENTS_V1: quando a barra vem no template inicial, o
// injector de compatibilidade não entra no ramo que fazia o bind dos botões.
// Anexa os eventos uma única vez, sem recriar a barra nem seus ícones.
const bindStageViewTabsEventsV1 = ViewLayer.prototype.bind;
ViewLayer.prototype.bind = function (...args) {
  const result = bindStageViewTabsEventsV1?.apply(this, args);
  this.querySelectorAll("nav.stage-view-tabs").forEach((nav) => {
    if (nav.dataset.stageTabsEventsBound === "true") return;
    nav.dataset.stageTabsEventsBound = "true";
    nav.querySelectorAll("[data-stage-view]").forEach((button) =>
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const next = button.dataset.stageView,
          { model, record: stage } = stageContextV1(),
          state = appStore.get();
        appStore.set({
          view: next,
          selectedStage: stage.id || state.selectedStage,
          selectedStageV9: model?.key || state.selectedStageV9,
          activityDedicated: false,
          stageActivityDedicatedV9: false,
          selectedActivity: null,
          activityRecordModalOpenV1: false,
          editingRecord: null,
          recordContext: null,
          stageRecordsContext: next === "records",
          recordFilters:
            next === "records"
              ? {
                  ...(state.recordFilters || {}),
                  stage: stage.name,
                  entity: "records",
                }
              : state.recordFilters,
          lastAction: `Abriu ${button.textContent.trim()} da etapa ${stage.name}`,
        });
      }),
    );
  });
  return result;
};

// RECORDS_STAGE_ENTRY_FINAL_V1: último contrato da tela de registros. Este
