const bindAiActionReflectionV1 = ViewLayer.prototype.bind;
ViewLayer.prototype.bind = function (...args) {
  const result = bindAiActionReflectionV1?.apply(this, args);
  this.querySelectorAll("[data-ai-reflection-apply]").forEach((button) => {
    if (button.dataset.reflectionBound === "true") return;
    button.dataset.reflectionBound = "true";
    button.addEventListener("click", () => {
      const id = button.dataset.aiReflectionApply,
        action = operationalActions().find((item) => item.id === id);
      if (!action) return;
      const currentState = appStore.get(),
        reflections = {
          ...(currentState.aiScheduleReflections || {}),
          [id]: {
            at: new Date().toISOString(),
            eta: action.eta,
            phase: action.phase,
            relation: action.relation,
            position: currentState.aiActionPositionChanges?.[id] || null,
          },
        };
      appStore.set({
        aiScheduleReflections: reflections,
        lastAction: `Refletiu a ação ${action.label} no cronograma`,
      });
      notify(
        "Inferência baseada no gráfico registrada no cronograma operacional.",
        "success",
      );
    });
  });
  return result;
};

// DASHBOARD_TIMELINE_FIRST_V1: o cronograma é a primeira leitura operacional
// depois do cabeçalho; mapa, KPIs e widgets continuam abaixo dele.
const renderTimelineFirstV1 = ViewLayer.prototype.render;
ViewLayer.prototype.render = function (...args) {
  const result = renderTimelineFirstV1?.apply(this, args);
  const home = this.querySelector(".dashboard-carbon-home"),
    head = home?.querySelector(".dashboard-carbon-head"),
    timeline = home?.querySelector(".dashboard-stage-timeline");
  if (home && head && timeline) head.after(timeline);
  return result;
};

// MAP_CONTEXT_CTA_V2: os CTAs do resumo pertencem ao mapa, não à navegação
// genérica. Isso evita que listeners de versões antigas capturem o clique.
const bindMapContextCtaV2 = ViewLayer.prototype.bind;
ViewLayer.prototype.bind = function (...args) {
  const result = bindMapContextCtaV2?.apply(this, args);
  this.querySelectorAll("[data-map-widget-context]").forEach((button) => {
    if (
      button.dataset.mapWidgetContextBound === "true" ||
      button.closest("map-filter-rail")
    )
      return;
    button.dataset.mapWidgetContextBound = "true";
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopImmediatePropagation();
      const source = button.closest(
          "[data-map-summary-widget],[data-highlight-status]",
        ),
        key =
          source?.dataset.mapSummaryKey ||
          source?.dataset.highlightStatus ||
          appStore.get().mapFilter ||
          "execution",
        filter =
          dashboardFilters.find((item) => item[0] === key) ||
          dashboardFilters[0],
        nextView = button.dataset.mapWidgetContext || "map";
      if (key === "progress") {
        const map =
          document.querySelector("map-scene[data-dashboard-operational-map]") ||
          document.querySelector("map-scene:not([compact])");
        map?.setMapSelectionMode("progress");
      }
      appStore.set({
        view: nextView,
        mapFilterWidget: key,
        lastAction: `Abriu contexto de ${filter[1]} no mapa`,
      });
    });
  });
  return result;
};

